import {addWeavePattern, createWeaveProject, duplicateWeaveWithVariation, hydrateProject, serializeProject, validateProject} from './weave-model.mjs';

const $ = id => document.getElementById(id);
const STORE = 'bac-weave-generator-projects-v1';
const clone = value => structuredClone(value);
const makeId = prefix => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
const defaultBoundary = () => ({id:'boundary-default',name:'DEFAULT SQUARE',type:'rect',points:[{x:-250,y:-250},{x:250,y:-250},{x:250,y:250},{x:-250,y:250}],createdAt:new Date().toISOString()});

function freshProject(name='WEAVE STUDIES') { const project=createWeaveProject(name); project.boundary=defaultBoundary(); return project; }
function loadStore(){try{const saved=JSON.parse(localStorage.getItem(STORE)); if(saved?.projects?.length){saved.projects=saved.projects.map(hydrateProject); return saved;}}catch{} const project=freshProject(); return {activeProjectId:project.id,projects:[project]};}
let store=loadStore(), mode=localStorage.getItem('bac-weave-display-mode-v1')||'light', drawing=false, draft=[];
function active(){return store.projects.find(project=>project.id===store.activeProjectId)||store.projects[0];}
function save(){localStorage.setItem(STORE,JSON.stringify(store));}
function summary(project=active()){return `${String(project.weavePatterns.length).padStart(2,'0')} WEAVES · ${String(project.pointSets.length).padStart(2,'0')} POINT SETS · ${String(project.polylineSets.length).padStart(2,'0')} POLYLINE SETS`;}
function renderPreview(){const project=active(), boundary=draft.length?draft:project.boundary?.points||defaultBoundary().points, toCanvas=p=>({x:410+p.x,y:360-p.y}), d=boundary.map(toCanvas), path=`M${d.map(p=>`${p.x} ${p.y}`).join(' L')}${draft.length>2?' Z':''}`; $('weave-preview').innerHTML=`<path d="${path}" fill="none" stroke="currentColor" stroke-width="1.5" vector-effect="non-scaling-stroke"/><g class="preview-corners">${d.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="3"/>`).join('')}</g>`; $('weave-preview').style.display=$('show-boundary').checked?'':'none';}
function renderBoards(){const project=active(); $('project-list').innerHTML=store.projects.map(p=>`<section class="board-node ${p.id===project.id?'active':''}"><div class="board-node-heading"><button class="project-item ${p.id===project.id?'active':''}" data-project="${p.id}">${p.name}<span>${String(p.weavePatterns.length).padStart(2,'0')}</span></button></div>${p.id===project.id?`<div class="board-children"><div class="iteration-heading"><span>BOUNDARY</span></div><div class="weave-row"><span>01</span><button data-boundary="1">${p.boundary?.name||'UNSAVED BOUNDARY'}</button><small>${p.boundary?.type?.toUpperCase()||'DEFAULT'} · ${p.boundary?.points?.length||0} POINTS</small></div><div class="iteration-heading"><span>WEAVE PATTERN GRIDS</span></div>${p.weavePatterns.length?p.weavePatterns.map((w,i)=>`<div class="weave-row"><span>${String(i+1).padStart(2,'0')}</span><button data-weave="${w.id}">${w.name}</button><small>SEED ${w.seed}</small></div>`).join(''):'<p class="iteration-empty">NO SAVED WEAVE PATTERNS.</p>'}<div class="lineage-summary">POINT SETS ${String(p.pointSets.length).padStart(2,'0')}<br>POLYLINE SETS ${String(p.polylineSets.length).padStart(2,'0')}</div></div>`:''}</section>`).join('');}
function render(){const project=active(),pts=project.boundary?.points||defaultBoundary().points,b={width:Math.round(Math.max(...pts.map(p=>p.x))-Math.min(...pts.map(p=>p.x))),height:Math.round(Math.max(...pts.map(p=>p.y))-Math.min(...pts.map(p=>p.y)))}; $('project-label').textContent=project.name; $('project-name').value=project.name; $('boundary-name').value=project.boundary?.name||'UNSAVED BOUNDARY'; $('boundary-kind').textContent=drawing?'DRAWING':project.boundary?.type?.toUpperCase()||'DEFAULT';$('boundary-size').textContent=`${b.width} × ${b.height}`; $('object-summary').textContent=summary(project); $('lineage-status').textContent=`WEAVE → POINTS → POLYLINES / ${validateProject(project).valid?'LINEAGE VALID':'LINEAGE ERROR'}`; renderBoards(); renderPreview();}
function setMode(next){mode=['light','dark','neo'].includes(next)?next:'light'; document.body.classList.toggle('mode-dark',mode==='dark');document.body.classList.toggle('mode-neo',mode==='neo');document.querySelectorAll('.mode-tab').forEach(button=>button.classList.toggle('active',button.dataset.mode===mode));localStorage.setItem('bac-weave-display-mode-v1',mode);}
function saveBoundary(){const project=active(),points=draft.length>=3?draft:project.boundary?.points||defaultBoundary().points; project.boundary={...defaultBoundary(),id:makeId('boundary'),name:$('boundary-name').value.trim().toUpperCase()||'UNTITLED BOUNDARY',type:draft.length?'drawn':project.boundary?.type||'rect',points};draft=[];drawing=false;project.updatedAt=new Date().toISOString();save();render();$('status').textContent=`SAVED ${project.boundary.name} IN ${project.name}.`;}
function saveWeave(){const project=active(), input={name:$('pattern-name').value,seed:$('seed').value,boundaryId:project.boundary?.id||null,lattice:{mode:'rectangular',spacing:40,angle:0,offset:0,visible:true},threadFamilies:[],influenceFields:[],threads:[],provenance:{release:'BUILD 01',createdFrom:'saved-state-controls'}}, result=addWeavePattern(project,input);store.projects=store.projects.map(p=>p.id===project.id?result.project:p);save();render();$('status').textContent=`SAVED ${result.pattern.name}. IT IS READY TO BECOME A SOURCE FOR POINT SETS.`;}
function duplicateWeave(){const project=active(), source=project.weavePatterns.at(-1);if(!source){$('status').textContent='SAVE A WEAVE PATTERN BEFORE CREATING A VARIATION.';return;}const result=duplicateWeaveWithVariation(project,source.id,{name:`${source.name} VARIATION`,seed:$('seed').value||source.seed});store.projects=store.projects.map(p=>p.id===project.id?result.project:p);save();render();$('status').textContent=`DUPLICATED ${source.name} WITH PRESERVED ANCESTRY.`;}

$('new-project').addEventListener('click',()=>{const name=prompt('Board name','WEAVE STUDIES');if(name===null)return;const project=freshProject(name);store.projects.push(project);store.activeProjectId=project.id;save();render();});
$('rename-project').addEventListener('click',()=>{$('project-name').focus();$('project-name').select();});
$('project-name').addEventListener('change',event=>{active().name=event.target.value.trim().toUpperCase()||active().name;active().updatedAt=new Date().toISOString();save();render();});
$('project-list').addEventListener('click',event=>{const board=event.target.closest('[data-project]');if(board){store.activeProjectId=board.dataset.project;save();render();return;}const weave=event.target.closest('[data-weave]');if(weave){const item=active().weavePatterns.find(w=>w.id===weave.dataset.weave);$('pattern-name').value=item.name;$('seed').value=item.seed;$('status').textContent=`LOADED ${item.name}. SOURCE WEAVE IS PRESERVED.`;}});
$('save-boundary').addEventListener('click',saveBoundary); $('save-weave').addEventListener('click',saveWeave);$('duplicate-weave').addEventListener('click',duplicateWeave);
$('import-boundary').addEventListener('click',()=>$('boundary-file').click());$('boundary-file').addEventListener('change',async e=>{const t=await e.target.files?.[0]?.text(),n=new DOMParser().parseFromString(t||'','image/svg+xml').querySelector('polygon,polyline'),v=(n?.getAttribute('points')||'').trim().split(/[ ,]+/).map(Number);if(v.length<6){$('status').textContent='IMPORT A CLOSED SVG POLYGON OR POLYLINE.';return;}let p=v.reduce((a,x,i)=>(i%2?a[a.length-1].y=x:a.push({x,y:0}),a),[]),xs=p.map(q=>q.x),ys=p.map(q=>q.y),s=500/Math.max(Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys));draft=p.map(q=>({x:(q.x-(Math.max(...xs)+Math.min(...xs))/2)*s,y:(q.y-(Math.max(...ys)+Math.min(...ys))/2)*s}));drawing=false;render();$('status').textContent='SVG BOUNDARY FIT TO CANVAS. CLICK SAVE BOUNDARY.';});$('draw-boundary').addEventListener('click',()=>{drawing=true;draft=[];$('status').textContent='DRAW MODE: CLICK THREE OR MORE POINTS ON THE CANVAS, THEN SAVE BOUNDARY.';render();});$('clear-boundary').addEventListener('click',()=>{draft=[];drawing=false;render();});
$('canvas').addEventListener('click',e=>{if(!drawing)return;const r=$('canvas').getBoundingClientRect(),x=(e.clientX-r.left)*820/r.width-410,y=360-(e.clientY-r.top)*720/r.height;draft.push({x,y});renderPreview();$('status').textContent=`DRAW MODE: ${draft.length} POINTS. ADD MORE OR SAVE BOUNDARY.`;});
$('show-boundary').addEventListener('change',renderPreview);$('show-grid').addEventListener('change',()=>{$('grid-layer').style.display=$('show-grid').checked?'':'none';$('frame-layer').style.display=$('show-grid').checked?'':'none';});
document.querySelectorAll('.mode-tab').forEach(button=>button.addEventListener('click',()=>setMode(button.dataset.mode)));
$('toggle-projects').addEventListener('click',()=>{const hidden=$('app-shell').classList.toggle('projects-hidden');$('toggle-projects').textContent=hidden?'BOARDS +':'BOARDS −';});
$('toggle-controls').addEventListener('click',()=>{const hidden=$('app-shell').classList.toggle('controls-hidden');$('toggle-controls').textContent=hidden?'CONTROLS +':'CONTROLS −';});
setMode(mode);render();
window.weaveState={get project(){return clone(active())},serialize:()=>serializeProject(active())};
